P = [
 dict(pmid='43043771', doi='10.1097/hjh.0000000000004498', journal='J Hypertens', title="Changes in air pollution-avoidance behaviour and blood pressure following an AirHealth behavioural intervention among adults in Nigeria: a quasi-experimental study.", short='Ibadan AirHealth co-created behavioural intervention COM-B avoidance SBP pre-post 607 adults', design='Intervention field trial (non-randomised)', pm='No PM measurement; air-pollution-avoidance behaviour by 11-item COM-B score', geo='Nigeria (Ibadan)', endpoint='Systolic and diastolic blood pressure; avoidance-behaviour score', tier='C', basis='Proxy / questionnaire', affil='Osun State University, Nigeria; University of Ibadan, Nigeria', n='Pre-post quasi-experiment in 607 apparently healthy, highly exposed adults in Ibadan; 12-week co-created AirHealth intervention (video documentary plus community education). Mean SBP fell by 4.58 mmHg (95% CI 1.43-7.74); DBP change was not significant. Unimproved avoidance behaviour predicted unimproved BP (aOR 2.87, 1.87-3.80). There is no control group, no exposure measurement and baseline SBP SD of 30.6 mmHg, so regression to the mean, seasonality and white-coat effects cannot be excluded, and nothing ties the BP change to reduced PM dose. Relevance: indirect - the trial needs exactly the personal or community sensor layer it lacks to show behaviour changed exposure.', sub=corpus.CVM),
 dict(pmid='43040085', doi='10.1007/s00484-026-03375-2', journal='Int J Biometeorol', title='Climate-specific short-term associations between ambient temperature, air pollution, and acute myocardial infarction in Israel.', short='Israel Rambam Soroka 2000-2018 time-series AMI temperature NO2 PM2.5 PM10 Mediterranean vs semi-arid', design='Time-series', pm='Daily ambient PM2.5, PM10, NO2, O3 with lags 0-3 d; source of exposure not stated in abstract', geo='Israel', endpoint='Daily AMI hospitalisations', tier='C', affil='Ben-Gurion University of the Negev, Israel; Rambam Healthcare Campus, Israel', n='Two-hospital time-series, 2000-2018: 18,229 AMI admissions in Mediterranean northern Israel and 30,208 in semi-arid southern Israel; Poisson/negative-binomial GLMs with lags to 3 days. Temperature dominates: higher Tmax lowered AMI risk in the north (lag 2 IRR 0.991, 0.986-0.997) and raised it in southern summers (lag 1 IRR 1.031, 1.011-1.050). The abstract reports only "small but statistically significant" associations for PM2.5 and NO2 in the north and none in the south, with no PM effect size, increment or CI. Single-hospital catchments and unstated monitor assignment limit exposure accuracy, and desert-dust PM10 is not separated. Relevance: low - the PM result is unquantified; climate-specific effect modification is the transferable point.', sub=corpus.CVM),
 dict(pmid='', doi='10.20944/preprints202611.1584.v1', journal='Preprints.org', title='Air Pollution and Primary Myocardial Infarction: An Ecological Study in a Low-Risk European Region', short='Madrid metro 2013-2018 CP-STEMI 4406 cases quasi-Poisson IDW monitors PM2.5', design='Ecological', pm='Municipal daily PM2.5, PM10, NO2 and others from inverse-distance-weighted regulatory stations to municipality centroid', geo='Spain (Madrid)', endpoint='ST-elevation MI with angiographically demonstrated culprit plaque', tier='C', basis='Reference / regulatory monitor', affil='not stated in record; not stated in record', n='Preprint, Madrid metropolitan area 2013-2018: 4,406 culprit-plaque STEMI cases (CP-STEMI) linked by municipality to inverse-distance-weighted daily station data; quasi-Poisson regression on prior-day exposures. The authors conclude an increased CP-STEMI risk independently associated with PM2.5 and a cold effect, but the results section of the abstract is truncated after "Particulate matter", so no estimate, lag or CI is available. NO2 exceeded the WHO level on more than half of days. Strengths: a tight case definition that reduces outcome misclassification. Weaknesses: centroid-IDW exposure for whole municipalities and an ecological design. Relevance: moderate - IDW from a sparse network is the exposure step a dense LCS mesh would replace.', sub=corpus.CVM),
 dict(pmid='43045424', doi='10.1016/j.iac.2026.08.009', journal='Immunol Allergy Clin North Am', title='The Air We Breathe: Utilizing Local Environmental Monitoring to Direct Allergy Care.', short='Colorado review monitoring for allergy care regulatory networks pollen community sensors personal monitors EHR', design='Narrative review', pm='Regulatory networks, pollen surveillance, community sensor networks, models, indoor and personal monitors', geo='United States', endpoint='Allergic disease management (clinical integration of exposure data)', tier='C', basis='Review / no primary exposure', affil='University of Colorado Anschutz, USA; University of Colorado Anschutz, USA', n='Narrative review for allergists of the exposure-data options available to clinical practice: regulatory air-quality networks, pollen surveillance, community low-cost sensor networks, modelling tools, and indoor and personal monitors. It weighs evidence for clinical relevance and sets out practical routes to integrate exposure data into patient-centred care, naming data validation, workflow integration and EHR interoperability as the barriers. No new data or quantitative synthesis; the abstract gives no criteria for when sensor data are trustworthy enough to act on. Relevance: direct - one of few clinical reviews that treats community LCS networks as a care input, and it frames validation as the gating problem.', sub=corpus.RESP),
]
